import type { I18n } from "@moku-labs/game";

/** One plain argument: an element stays an element, a list and a number go through Intl. */
function argument(value: unknown, intl: I18n.IntlKit): I18n.Part {
  if (Array.isArray(value)) {
    return { kind: "text", text: intl.list().format(value as readonly string[]) };
  }

  if (typeof value === "number") return { kind: "text", text: intl.number().format(value) };

  if (
    typeof value === "object" &&
    value !== null &&
    "type" in value &&
    "props" in value &&
    "children" in value
  ) {
    return { kind: "element", node: value as I18n.ElementNode };
  }

  return { kind: "text", text: String(value) };
}

